const body = $json.body ?? $json;
const question = String(body.question ?? '').trim();
if (!question) throw new Error('Missing required field: question');
return [{json:{question, quarter: body.quarter || null, document_type: body.document_type || null, top_k: Math.min(Number(body.top_k || 5), 10)}}];

const e = $json.data?.[0]?.embedding;
if (!Array.isArray(e) || e.length !== 1536) throw new Error('OpenAI embedding missing or not 1536 dimensions. Confirm text-embedding-3-small and SQL vector(1536).');
const original = $('Validate Input').item.json;
return [{json:{...original, query_embedding:e}}];

const rows = Array.isArray($json) ? $json : ($json.data || []);
const input = $('Prepare Vector Search').item.json;
const evidence = rows.filter(r => Number(r.similarity ?? 0) >= 0.25).map((r,i)=>({citation:`[${r.document_id} | ${r.quarter} | ${r.page_or_timestamp || r.section} | ${r.source_file}]`, document_id:r.document_id, quarter:r.quarter, speaker:r.speaker, source_file:r.source_file, section:r.section, timestamp:r.page_or_timestamp, similarity:Number(r.similarity ?? 0), text:r.content}));
const context = evidence.map((e,i)=>`SOURCE ${i+1} ${e.citation}
${e.text}`).join('

---

');
return [{json:{question:input.question, quarter:input.quarter, evidence, context, evidence_count:evidence.length}}];

const raw = $json.choices?.[0]?.message?.content || '';
let parsed;
try { parsed = JSON.parse(raw); } catch { parsed = {answer_scaffold:raw || 'No answer returned.',risk_level:'High',guidance_gap:'Unable to parse model output.',missing_evidence:['Validate retrieved evidence and model response.'],citations:[],review_required:true}; }
const ctx = $('Build Cited Context').item.json;
return [{json:{...parsed, question:ctx.question, quarter:ctx.quarter, evidence:ctx.evidence, evidence_count:ctx.evidence_count, synthetic_data:true, human_review_required:true}}];
